<?php
namespace App\Http\Controllers\HR;use App\Http\Controllers\Controller;use App\Models\{Employee,StaffShift,StaffShiftAssignment};use Illuminate\Http\Request;class ShiftController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('hr.shifts',['shifts'=>StaffShift::where('property_id',$p)->get(),'employees'=>Employee::where('property_id',$p)->where('status','active')->get(),'assignments'=>StaffShiftAssignment::with(['employee','shift'])->whereHas('employee',fn($q)=>$q->where('property_id',$p))->whereDate('shift_date','>=',today())->orderBy('shift_date')->limit(100)->get()]);}public function store(Request $r){$p=auth()->user()->property_id;$d=$r->validate(['name'=>'required|max:100','starts_at'=>'required','ends_at'=>'required','break_minutes'=>'nullable|integer|min:0']);$d['property_id']=$p;$d['is_overnight']=$d['ends_at']<=$d['starts_at'];StaffShift::create($d);return back()->with('success','Shift created.');}public function assign(Request $r){$d=$r->validate(['employee_id'=>'required|integer','staff_shift_id'=>'required|integer','shift_date'=>'required|date']);StaffShiftAssignment::updateOrCreate(['employee_id'=>$d['employee_id'],'shift_date'=>$d['shift_date']],$d);return back()->with('success','Shift assigned.');}}